var answers=[["先迈出很小的一步", "把问题缩小到今天能完成的一件事。"], ["给答案一点时间", "现在不必急着把所有空白填满。"], ["换一个问题试试", "问“我可以做什么”，也许比问“会怎样”更有用。"], ["你可以重新选择", "昨天的决定，不必成为今天的围墙。"], ["先听听自己的声音", "暂时关掉别人的期待，写下你真正想要的。"], ["把它说清楚", "一句坦诚的话，可能比许多猜测更有帮助。"], ["试着少做一件事", "给重要的事留出空间。"], ["让好奇带路", "不确定的时候，可以先去了解。"], ["今天适合整理", "整理桌面，也整理思路。"], ["允许事情慢慢发生", "有些生长不能靠催促完成。"], ["寻找第二种办法", "一条路暂时不通，不代表没有出口。"], ["先照顾好自己", "精力恢复之后，难题可能会变小。"], ["核实一个关键事实", "不要让想象承担证据的工作。"], ["向可信的人请教", "一个外部视角可能照亮盲点。"], ["留下一份记录", "写下来，便能看见变化。"], ["为自己设一道边界", "温和地拒绝，也是在保护重要的事。"], ["把期待说出来", "别人未必能猜中你需要什么。"], ["先做一个小实验", "用一次低成本尝试替代长久的犹豫。"], ["不必一次做到完美", "可以先完成，再慢慢打磨。"], ["给过去一个句号", "有些功课已经学会，可以向前了。"], ["观察，而非立即判断", "多看一会儿，也是一种行动。"], ["问问代价是什么", "愿意承担的部分，才是选择的重量。"], ["珍惜已经拥有的", "答案有时藏在被忽略的日常里。"], ["把注意力带回此刻", "眼前这一小步，比遥远的假设更具体。"], ["别替别人作答", "留一点空间，听听对方真正的意思。"], ["试着主动一次", "一句问候，可以成为新的开始。"], ["休息也算进展", "停下来，是为了继续走。"], ["让计划轻一点", "一个能坚持的计划，比宏大的清单更好。"], ["你可以说不知道", "诚实的空白，胜过仓促的确定。"], ["等情绪落地再决定", "不必在风最大的时候选方向。"], ["寻找你能改变的部分", "把精力交给有回应的地方。"], ["给自己一点善意", "像对待朋友那样，对待此刻的自己。"], ["删去一个不必要的承诺", "空出来的位置，可以留给真正喜欢的事。"], ["让行动回答你", "迈出一步后，再看下一步。"], ["先确认你的需要", "想要被理解，还是想要一个解决办法？"], ["留意那个反复出现的念头", "它也许在提醒一个尚未被照顾的需要。"], ["把复杂拆开", "逐件处理，就不必一次面对整座山。"], ["为完成庆祝一下", "看见走过的路，也是继续前行的力量。"], ["再听一遍对方的话", "放下准备反驳的念头，先理解。"], ["给新鲜事物一个位置", "今天可以容纳一点与往常不同。"], ["允许自己改变想法", "新的信息，值得一次新的判断。"], ["回到最初的原因", "是什么让你开始在意这件事？"], ["先把最坏的猜测写下", "再分辨：哪些是事实，哪些只是担心。"], ["留下一点余地", "不用把每一分钟都安排满。"], ["你不必独自完成", "合作可以从一个小请求开始。"], ["选择更可持续的节奏", "能够长久继续，比短暂冲刺更珍贵。"], ["把感谢表达出来", "让好的事情得到回应。"], ["这次，认真听自己的犹豫", "犹豫可能指出了需要补充的信息。"]],current=-1,saved={items:[]},loaded=false,inBookmarks=false,busy=false,error='';
