async function save(){if(!loaded||busy||saved.items.indexOf(current)>=0)return;busy=true;var next={items:saved.items.concat([current]).slice(-48)};page();try{if(!A)throw Error('预览不能永久保存');await A.save(next);saved=next;error='已保存书签'}catch(e){error='保存失败，请重试'}busy=false;page();}
